const r = await tools.exec_command({cmd:"cat > commands/check-integrity.py <<'PY'
import hashlib,json,os,stat
from pathlib import Path
root=Path(os.environ['STAMPED_JUDGE_TARGET'])
canon=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
initial=json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
print('manifest identity equal:', canon==initial)
ignore={'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}
expected={e['path'].removeprefix('content/workspace/'):e for e in initial['entries']}
actual={}
def walk(path,rel=''):
 for ent in os.scandir(path):
  rp=f'{rel}/{ent.name}' if rel else ent.name
  st=ent.stat(follow_symlinks=False)
  mode=stat.S_IMODE(st.st_mode)
  if ent.is_symlink():
   actual[rp]={'kind':'symlink','mode':mode,'target':os.readlink(ent.path)}
  elif ent.is_dir(follow_symlinks=False):
   actual[rp]={'kind':'directory','mode':mode}; walk(ent.path,rp)
  elif ent.is_file(follow_symlinks=False):
   h=hashlib.sha256()
   with open(ent.path,'rb') as f:
    for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
   actual[rp]={'kind':'file','mode':mode,'sha256':h.hexdigest(),'size':st.st_size}
  else: actual[rp]={'kind':'other','mode':mode}
walk(root)
changes=[]
for p in sorted(set(expected)|set(actual)):
 if p in ignore: continue
 a=expected.get(p); b=actual.get(p)
 if a != b: changes.append((p,a,b))
print('non-metadata changes:',len(changes))
for c in changes[:25]: print(c)
meta=[]
for p in sorted(ignore):
 a=expected.get(p); b=actual.get(p)
 if a!=b: meta.append({'path':p,'initial':a,'final':b})
print('permitted metadata differences:',json.dumps(meta))
PY
